using System.Text;
using VoXelSharp.Protocol;

namespace VoXelSharp.Tests;

public class CompressionTests
{
    // Known-good zlib streams generated by the reference (Python) zlib implementation,
    // independent of .NET's ZLibStream.
    public static TheoryData<byte[], byte[]> KnownGoodVectors => new()
    {
        { Convert.FromHexString("789c030000000001"), Array.Empty<byte>() },
        { Convert.FromHexString("789cf348cdc9c9d75108cb8f48cd09ce482c2a5004003bca064e"),
            Encoding.UTF8.GetBytes("Hello, VoXelSharp!") },
    };

    [Theory]
    [MemberData(nameof(KnownGoodVectors))]
    public void DecompressDecodesReferenceZlibStreams(byte[] compressed, byte[] expected)
    {
        byte[] actual = Compression.Decompress(compressed);

        Assert.Equal(expected, actual);
    }

    [Theory]
    [MemberData(nameof(RoundTripValues))]
    public void CompressThenDecompressIsRoundTrip(byte[] source)
    {
        byte[] compressed = Compression.Compress(source);

        byte[] decompressed = Compression.Decompress(compressed);

        Assert.Equal(source, decompressed);
    }

    [Theory]
    [MemberData(nameof(RoundTripValues))]
    public void CompressedOutputRecompressesStable(byte[] source)
    {
        byte[] first = Compression.Compress(source);
        byte[] second = Compression.Compress(source);

        Assert.Equal(first, second);
    }

    [Fact]
    public void CompressedOutputStartsWithZlibHeader()
    {
        byte[] compressed = Compression.Compress(Encoding.UTF8.GetBytes("VoXelSharp"));

        Assert.Equal(0x78, compressed[0]); // zlib CMF byte
    }

    [Theory]
    [MemberData(nameof(MalformedInputs))]
    public void DecompressMalformedInputThrows(byte[] input)
    {
        Assert.Throws<InvalidDataException>(() => Compression.Decompress(input));
    }

    [Theory]
    [MemberData(nameof(MalformedInputs))]
    public void TryDecompressMalformedInputReturnsFalse(byte[] input)
    {
        Assert.False(Compression.TryDecompress(input, out byte[]? result));
        Assert.Null(result);
    }

    [Fact]
    public void DecompressTruncatedStreamThrows()
    {
        byte[] compressed = Compression.Compress(new byte[16384]);
        byte[] truncated = compressed[..(compressed.Length - 8)].ToArray();

        Assert.Throws<InvalidDataException>(() => Compression.Decompress(truncated));
    }

    [Fact]
    public void DecompressCorruptedTrailerThrows()
    {
        // The deflate payload is intact; only the final ADLER-32 trailer byte is corrupted,
        // so this exercises the trailer-checksum rejection path (ZLibStream alone would
        // silently accept it).
        byte[] compressed = Compression.Compress(new byte[16384]);
        compressed[^1] ^= 0xFF;

        Assert.Throws<InvalidDataException>(() => Compression.Decompress(compressed));
        Assert.False(Compression.TryDecompress(compressed, out _));
    }

    [Fact]
    public void DecompressEmptyInputThrows()
    {
        Assert.Throws<InvalidDataException>(() => Compression.Decompress(ReadOnlySpan<byte>.Empty));
    }

    [Fact]
    public void DecompressExceedingSafetyLimitThrows()
    {
        // Highly compressible data (zeros) that decompresses past the 8 MiB safety limit.
        byte[] oversized = new byte[Compression.MaxDecompressedLength + 1];
        byte[] compressed = Compression.Compress(oversized);

        Assert.Throws<InvalidDataException>(() => Compression.Decompress(compressed));
    }

    [Fact]
    public void DecompressAtExactSafetyLimitSucceeds()
    {
        byte[] exact = new byte[Compression.MaxDecompressedLength];
        byte[] compressed = Compression.Compress(exact);

        byte[] decompressed = Compression.Decompress(compressed);

        Assert.Equal(exact, decompressed);
    }

    [Fact]
    public void TryDecompressValidInputReturnsTrue()
    {
        byte[] source = Encoding.UTF8.GetBytes("TryDecompress");

        bool success = Compression.TryDecompress(Compression.Compress(source), out byte[]? result);

        Assert.True(success);
        Assert.NotNull(result);
        Assert.Equal(source, result);
    }

    [Fact]
    public void CompressEmptyInputProducesReferenceZlibStream()
    {
        byte[] expected = Convert.FromHexString("789c030000000001");

        byte[] compressed = Compression.Compress(Array.Empty<byte>());

        Assert.Equal(expected, compressed);
    }

    [Fact]
    public void CompressEmptyInputProducesValidZlibStream()
    {
        byte[] compressed = Compression.Compress(Array.Empty<byte>());

        byte[] decompressed = Compression.Decompress(compressed);

        Assert.Empty(decompressed);
    }

    public static TheoryData<byte[]> RoundTripValues => new()
    {
        { Array.Empty<byte>() },
        { Encoding.UTF8.GetBytes("a") },
        { Encoding.UTF8.GetBytes("Hello, VoXelSharp!") },
        { new byte[] { 0x00, 0x01, 0x02, 0x03, 0xFF, 0xFE, 0xFD } },
        { Encoding.UTF8.GetBytes("The quick brown fox jumps over the lazy dog. xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx") },
        { new byte[4096] }, // all zeros, highly compressible
        { RandomBytes(16384) },
    };

    public static TheoryData<byte[]> MalformedInputs => new()
    {
        { Convert.FromHexString("00000000") },           // not a zlib header
        { Convert.FromHexString("78") },                  // truncated header
        { new byte[] { 0x78, 0x9C } },                    // valid header, no data
        { Convert.FromHexString("deadbeef") },            // garbage
        { Encoding.UTF8.GetBytes("this is not zlib") },   // plain text
    };

    private static byte[] RandomBytes(int count)
    {
        byte[] bytes = new byte[count];
        System.Random.Shared.NextBytes(bytes);
        return bytes;
    }
}
